  "noticeReopen": "Oznámení o úložišti",
  "noticeLabel": "Oznámení o úložišti prohlížeče",
  "noticeText": "Cook používá úložiště prohlížeče pro funkce vaření a přihlášení, které používáte. Nepřidává se žádné reklamní ani analytické úložiště.",
  "noticeClose": "Zavřít oznámení o úložišti",
  "privDraftLabel": "Koncept — aktualizováno 28. října 2026.",
  "privDraft": "Funkce účtu se právě testují. Níže uvedené údaje o provozovateli a službách je nutné doplnit před veřejným spuštěním.",
  "privWho1": "Cook provozuje [úřední název a poštovní adresa provozovatele]. S dotazy a žádostmi o ochraně soukromí se obraťte na [e-mail pro ochranu soukromí]. Tyto údaje je nutné doplnit před otevřením registrace.",
  "privWhat1": "Když si vytvoříte účet, používáme váš e-mail, identifikátor účtu, záznamy o ověření heslem a stav potvrzení, abychom mohli účet poskytovat a chránit. Hesla zpracovává poskytovatel ověřování jako bezpečné hashe; Cook neukládá čitelná hesla. Ukládáme uspořádání kuchyně, zvolený jazyk, motiv a jednotky, abychom obnovili vaše nastavení na všech zařízeních. K účtu je potřeba e-mail a heslo; recepty můžete procházet i bez účtu.",
  "privWhat2": "Zpracování účtu a nastavení je nezbytné k poskytování služby účtu, o kterou žádáte (čl. 6 odst. 1 písm. b) GDPR). Omezené záznamy pro zabezpečení a prevenci zneužití mohou být zpracovávány na základě oprávněných zájmů (čl. 6 odst. 1 písm. f)), v nezbytném rozsahu a po vyvážení zájmů. E-maily k ověření a obnovení hesla jsou servisní zprávy, nikoli marketing. Funkce účtu nepřidává reklamu ani analytiku.",
  "privStorage1": "Cook používá sessionStorage k přenosu vaší kuchyně, postupu vaření a voleb mezi stránkami ve stejné kartě. Když jste přihlášeni, uchovává také vaši přihlašovací relaci. Prohlížeč tato data obvykle smaže po skončení relace karty, ale obnovení relace prohlížeče je může zachovat. Odhlášení smaže data karty Cook. Zavření oznámení o úložišti se pamatuje jen v dané kartě. Vlastní skripty Cook nenastavují cookies. Vaši poskytovatelé hostingu nebo služeb mohou provádět vlastní bezpečnostní zpracování, které je třeba před spuštěním zdokumentovat.",
  "privStorage2": "OK a tlačítko pro zavření oznámení o úložišti oznámení pouze zavřou. Nepovolují analytiku, reklamu ani jiné volitelné sledování. Jakékoli budoucí nepotřebné ukládání bude vyžadovat samostatnou volbu ještě před zahájením, se stejně snadným odmítnutím a odvoláním.",
  "privOther1": "Současná hlasová funkce seznamu receptů se podle vaší IP adresy ptá služby country.is na přibližnou zemi, aby zvolila jazyk rozpoznávání řeči. Pokud používáte rozpoznávání z mikrofonu, prohlížeč může posílat zvuk svému poskytovateli rozpoznávání řeči. Suroviny můžete také napsat. Tito poskytovatelé, jejich zásady a právní základ těchto funkcí musí být před veřejným spuštěním přezkoumány.",
  "privProviders1": "Plánovaný poskytovatel účtů: Supabase (spravovaný PostgreSQL a ověřování) se zvolenou oblastí databáze v EU. Poskytovatel e-mailu: [poskytovatel]. Hosting webu: [poskytovatel]. Provozovatel musí potvrdit skutečné poskytovatele, smlouvy o zpracování, dílčí zpracovatele, umístění logů a případné předávání mimo EHP. Oblast databáze v EU sama o sobě nevylučuje mezinárodní předávání. V příslušných případech uveďte rozhodnutí o odpovídající ochraně nebo smluvní záruky a jak získat jejich kopii.",
  "privRetention1": "Nastavení účtu se uchovává, dokud je váš účet aktivní. O výmaz můžete požádat přes výše uvedený kontakt pro ochranu soukromí. Před spuštěním musí provozovatel stanovit postup vyřizování žádostí o výmaz, vypršení neověřených účtů a dobu uchovávání bezpečnostních logů a záloh. Smazaná data mohou zůstat v zálohách s omezeným přístupem až do konce zdokumentované doby uchovávání.",
  "privRights1": "V závislosti na platných podmínkách můžete požadovat přístup, opravu, výmaz, omezení zpracování nebo přenositelnost, případně vznést námitku proti zpracování na základě oprávněného zájmu. Obraťte se na výše uvedeného provozovatele; na žádosti se obvykle odpovídá do jednoho měsíce a případné zákonné prodloužení se vysvětlí. Můžete podat stížnost u dozorového úřadu, včetně maďarského NAIH na naih.hu. Cook nepoužívá nastavení účtu k automatizovanému rozhodování s právními nebo podobně významnými účinky.",
