  "Fill the pot": "Naplnit hrnec",
  "Fill the large pot with # L cold water. Don't add oil.": "Naplňte velký hrnec # l studené vody. Olej nepřidávejte.",
  "Pot filled": "Hrnec naplněný",
  "Put it on the stove": "Postavit na sporák",
  "Put the pot on the largest burner, turn it to HIGH and put the lid on (it boils faster).": "Postavte hrnec na největší plotýnku, nastavte VYSOKÝ výkon a přikryjte pokličkou (rychleji se vaří).",
