  "Scoop dumpling-sized portions into bowls with a big spoon, pour over the chocolate sauce and top with whipped cream.": "Velkou lžící nabírejte porce velikosti noku do misek, přelijte čokoládovou omáčkou a ozdobte šlehačkou.",
